// NewCommand returns the `entire review` cobra command wired with the
// provided deps. Callers in the cli package pass a fully-populated Deps;
// tests pass a Deps with stub fields.
func NewCommand(deps Deps) *cobra.Command {
	var configure bool
	var edit bool
	var agentOverride string
	var modelOverride string
	var baseOverride string
	var profileOverride string
	var perRunPrompt string
	var findings bool
	var listModels bool
	var listAgents bool
	var listProfiles bool
	var setAgents []string
	var setJudge string
	var setOutput string
	var setLocal bool
	var reviewTimeout time.Duration
	var setTask string
	var setModels []string
	var setSlots []string
	var target string
	var cleanupWorktree bool
	var trustTarget string
	var showConfig bool
	var showConfigJSON bool

	cmd := &cobra.Command{
		Use: "review",
		// Hidden from `entire help` while the feature is still maturing —
		// users who know about it can still run `entire review` / `entire
		// review --help` and the command works normally.
		Hidden: true,
		Short:  "Run a multi-agent review against a branch",
		Long:   reviewLongHelp,
		Args: func(_ *cobra.Command, args []string) error {
			if len(args) > 1 {
				return fmt.Errorf("accepts at most one argument, received %d", len(args))
			}
			if len(args) == 1 && profileOverride != "" && !findings {
				return errors.New("pass profile either positionally or with --profile, not both")
			}
			return nil
		},
		RunE: func(cmd *cobra.Command, args []string) error {
			ctx := cmd.Context()
			// Discover external agents so review configs that target them
			// resolve correctly — without this, GetAgentsWithHooksInstalled
			// and agent.Get can't see them. Before --target too: the gate also
			// needs their declared caller variables.
			external.DiscoverAndRegister(ctx)
			gateOpts := reviewGateOptions{
				TrustTarget:    trustTarget,
				Command:        reviewInvocation(cmd, args),
				AgentOverride:  agentOverride,
				ShowConfig:     showConfig,
				ShowConfigJSON: showConfigJSON,
			}
			if target != "" {
				return runTargetReview(ctx, cmd, targetReviewRequest{
					Target:          target,
					Positional:      args,
					ProfileOverride: profileOverride,
					CleanupWorktree: cleanupWorktree,
					ShowConfig:      showConfig,
					ShowConfigJSON:  showConfigJSON,
					ModeSelected:    configure || edit || findings || listProfiles || listAgents || listModels,
					Gate:            gateOpts,
				}, deps)
			}
			if cleanupWorktree {
				return errors.New("--cleanup-worktree requires --target")
			}

			if listModels {
				return runReviewListModels(ctx, cmd, agentOverride, deps)
			}
			if listAgents {
				listProfile := profileOverride
				if len(args) == 1 {
					listProfile = args[0]
				}
				return runReviewListAgents(ctx, cmd, listProfile, deps)
			}
			if listProfiles {
				return runReviewListProfiles(ctx, cmd, deps)
			}

			modes := 0
			for _, enabled := range []bool{configure, edit, findings} {
				if enabled {
					modes++
				}
			}
			if modes > 1 {
				return errors.New("--configure, --edit, and --findings are mutually exclusive")
			}
			if modelOverride != "" && agentOverride == "" {
				return errors.New("--model requires --agent (the model applies to a single reviewer)")
			}
			positionalArg := ""
			if len(args) == 1 {
				positionalArg = args[0]
			}
			profileName := profileOverride
			if positionalArg != "" && !findings {
				profileName = positionalArg
			}
			if configure {
				return runReviewConfigure(ctx, cmd, profileName, reviewConfigureOptions{
					Agents: setAgents,
					Judge:  setJudge,
					Output: setOutput,
					Local:  setLocal,
					Task:   setTask,
					Models: setModels,
					Slots:  setSlots,
				}, deps)
			}
			if edit {
				if !reviewCommandIsInteractive(cmd) {
					err := errors.New("--edit requires an interactive terminal")
					cmd.SilenceUsage = true
					fmt.Fprintln(cmd.ErrOrStderr(), "--edit requires an interactive terminal.")
					fmt.Fprintln(cmd.ErrOrStderr(), "Inspect current profiles with:")
					fmt.Fprintln(cmd.ErrOrStderr(), "  entire review --list")
					fmt.Fprintln(cmd.ErrOrStderr(), "For non-interactive changes, use:")
					fmt.Fprintln(cmd.ErrOrStderr(), "  entire review --configure --set-agents <agent>[,<agent>] [--set-judge <agent>]")
					return wrapReviewSilentError(deps.NewSilentError, err)
				}
				return RunReviewProfileConfigPicker(ctx, cmd.OutOrStdout(), deps.GetAgentsWithHooksInstalled, profileName)
			}
			if findings {
				return runReviewFindings(ctx, cmd, positionalArg, deps.NewSilentError)
			}
			// The flag flows through unmapped: RunConfig.ReviewerTimeout is
			// two-state (positive = hard cap, anything else = no cap), so the
			// default 0, an explicit --timeout 0, and a negative all mean
			// "reviewers run until done". The judge derives its own bound via
			// judgeTimeoutArg and is never uncapped.
			return runReview(ctx, cmd, agentOverride, modelOverride, baseOverride, profileName, perRunPrompt, reviewTimeout, gateOpts, deps)
		},
