		return stringPtr(trailReviewSeverityMedium)
	case strings.Contains(prefix, "[p3]") || strings.Contains(prefix, "[low]") || strings.Contains(prefix, "[nit]") || strings.Contains(prefix, "nit:"):
		return stringPtr(trailReviewSeverityLow)
	default:
		return nil
	}
}
