	synthesisProvider SynthesisProvider
	perRunPrompt      string
	profileName       string
	task              string
	masterName        string
	// judgeTimeout bounds the judge's consolidation call, following the same
	// three-state convention as the reviewer timeout (positive: use it; zero:
	// default; negative: disabled). Set from the resolved --timeout so one knob
	// governs both reviewers and the judge.
	judgeTimeout      time.Duration
	onSynthesisResult func(result string)
	onSynthesisError  func(err error)
}

type singleAgentSinkInputs struct {
	out       io.Writer
	isTTY     bool
	canPrompt bool
	agentName string
	cancelRun context.CancelFunc
}

// composeMultiAgentSinks builds the sink slice for a multi-agent run. The
// master adjudication phase (SynthesisSink) runs unconditionally when a
// provider is configured — it needs no stdin, so it is available in TTY,
// redirected, and CI output alike.
//
